-- The schema this chain leaves on a fresh database, printed from the catalogue.
-- Generated by `npm run schema:snapshot`; a test compares it with a fresh replay.

CREATE TABLE public.bootstrap_state (
  key text NOT NULL,
  value text NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT bootstrap_state_pkey PRIMARY KEY (key)
);

CREATE TABLE public.connect_attempt (
  id text NOT NULL,
  org text NOT NULL,
  created_by text NOT NULL,
  person text DEFAULT ''::text NOT NULL,
  plugin_id text NOT NULL,
  server text NOT NULL,
  created_at bigint NOT NULL,
  expires_at bigint NOT NULL,
  CONSTRAINT connect_attempt_pkey PRIMARY KEY (id)
);
CREATE INDEX idx_connect_attempt_expires ON public.connect_attempt USING btree (expires_at);
CREATE INDEX idx_connect_attempt_org ON public.connect_attempt USING btree (org);

CREATE TABLE public.connect_link (
  token_hash text NOT NULL,
  org text NOT NULL,
  vault_id text NOT NULL,
  address text NOT NULL,
  return_url text NOT NULL,
  created_by text NOT NULL,
  created_by_class text NOT NULL,
  created_by_bound_org text DEFAULT ''::text NOT NULL,
  created_at bigint NOT NULL,
  expires_at bigint NOT NULL,
  used_at bigint DEFAULT 0 NOT NULL,
  CONSTRAINT connect_link_pkey PRIMARY KEY (token_hash)
);
CREATE INDEX idx_connect_link_expires ON public.connect_link USING btree (expires_at);
CREATE INDEX idx_connect_link_org ON public.connect_link USING btree (org);
CREATE INDEX idx_connect_link_vault ON public.connect_link USING btree (vault_id);

CREATE TABLE public.file_blob_refs (
  file_id text NOT NULL,
  blob_key text COLLATE "C" NOT NULL,
  org text NOT NULL,
  CONSTRAINT file_blob_refs_pkey PRIMARY KEY (file_id)
);
CREATE INDEX idx_file_blob_refs_blob ON public.file_blob_refs USING btree (blob_key);
CREATE INDEX idx_file_blob_refs_org ON public.file_blob_refs USING btree (org);

CREATE TABLE public.file_blobs (
  blob_key text COLLATE "C" NOT NULL,
  org text NOT NULL,
  state text NOT NULL,
  size_bytes bigint DEFAULT 0 NOT NULL,
  expires_at bigint DEFAULT 0 NOT NULL,
  CONSTRAINT file_blobs_pkey PRIMARY KEY (blob_key)
);
CREATE INDEX idx_file_blobs_org ON public.file_blobs USING btree (org, blob_key);
CREATE INDEX idx_file_blobs_sweep ON public.file_blobs USING btree (state, expires_at);

CREATE TABLE public.grant_history (
  org text NOT NULL,
  sequence bigint NOT NULL,
  occurred_at text NOT NULL,
  change text NOT NULL,
  cause text NOT NULL,
  actor_id text NOT NULL,
  actor_class text NOT NULL,
  grant_id text NOT NULL,
  principal_kind text NOT NULL,
  principal_id text NOT NULL,
  principal_relation text DEFAULT ''::text NOT NULL,
  relation text NOT NULL,
  resource_kind text NOT NULL,
  resource_id text NOT NULL,
  data bytea NOT NULL,
  CONSTRAINT grant_history_cause_check CHECK (cause <> ''::text),
  CONSTRAINT grant_history_change_check CHECK (change = ANY (ARRAY['granted'::text, 'revoked'::text])),
  CONSTRAINT grant_history_pkey PRIMARY KEY (org, sequence)
);
CREATE INDEX grant_history_by_time ON public.grant_history USING btree (occurred_at, org, sequence);

CREATE TABLE public.grant_history_heads (
  org text NOT NULL,
  last_sequence bigint NOT NULL,
  last_occurred_at text NOT NULL,
  CONSTRAINT grant_history_heads_pkey PRIMARY KEY (org)
);

CREATE TABLE public.oauth_client_registration (
  login_server text NOT NULL,
  redirect_uri text NOT NULL,
  client_id text NOT NULL,
  created_at text NOT NULL,
  CONSTRAINT oauth_client_registration_pkey PRIMARY KEY (login_server, redirect_uri)
);
CREATE INDEX idx_oauth_client_registration_client ON public.oauth_client_registration USING btree (client_id);

CREATE TABLE public.organization_deletions (
  org text NOT NULL,
  phase text NOT NULL,
  marked_at text COLLATE "C" NOT NULL,
  accepted_at text COLLATE "C" DEFAULT ''::text NOT NULL,
  heartbeat_at text COLLATE "C" DEFAULT ''::text NOT NULL,
  stage text DEFAULT ''::text NOT NULL,
  last_error text DEFAULT ''::text NOT NULL,
  CONSTRAINT organization_deletions_pkey PRIMARY KEY (org)
);

CREATE TABLE public.pending_oauth_state (
  state text NOT NULL,
  code_verifier text NOT NULL,
  client_id text DEFAULT ''::text NOT NULL,
  client_secret text DEFAULT ''::text NOT NULL,
  token_endpoint text DEFAULT ''::text NOT NULL,
  identity_account_id text DEFAULT ''::text NOT NULL,
  auth_method text DEFAULT ''::text NOT NULL,
  token_auth_method text DEFAULT ''::text NOT NULL,
  redirect_uri text DEFAULT ''::text NOT NULL,
  org text DEFAULT ''::text NOT NULL,
  vault_id text DEFAULT ''::text NOT NULL,
  address text DEFAULT ''::text NOT NULL,
  login_app text DEFAULT ''::text NOT NULL,
  resource text DEFAULT ''::text NOT NULL,
  client_registration text DEFAULT ''::text NOT NULL,
  connect_link text DEFAULT ''::text NOT NULL,
  provider_name text DEFAULT ''::text NOT NULL,
  userinfo_url text DEFAULT ''::text NOT NULL,
  created_at bigint NOT NULL,
  CONSTRAINT pending_oauth_state_pkey PRIMARY KEY (state)
);
CREATE INDEX idx_pending_oauth_state_created ON public.pending_oauth_state USING btree (created_at);

CREATE TABLE public.resource_audit (
  id bigint DEFAULT nextval('resource_audit_id_seq'::regclass) NOT NULL,
  kind text NOT NULL,
  resource_id text NOT NULL,
  data bytea NOT NULL,
  archived_at timestamp with time zone DEFAULT now() NOT NULL,
  version_hash text,
  tag text,
  CONSTRAINT resource_audit_pkey PRIMARY KEY (id)
);
CREATE INDEX idx_audit_hash ON public.resource_audit USING btree (kind, resource_id, version_hash);
CREATE INDEX idx_audit_resource ON public.resource_audit USING btree (kind, resource_id);
CREATE INDEX idx_audit_tag ON public.resource_audit USING btree (kind, resource_id, tag, archived_at DESC);

CREATE TABLE public.resource_list_keys (
  kind text NOT NULL,
  id text NOT NULL,
  key text NOT NULL,
  value text NOT NULL,
  created_at text COLLATE "C" NOT NULL,
  CONSTRAINT resource_list_keys_pkey PRIMARY KEY (kind, id, key)
);
CREATE INDEX idx_resource_list_keys_lookup ON public.resource_list_keys USING btree (kind, key, value, created_at, id COLLATE "C");

CREATE TABLE public.resource_names (
  kind text NOT NULL,
  org text NOT NULL,
  name text NOT NULL,
  id text NOT NULL,
  state text NOT NULL,
  claimed_at text COLLATE "C" NOT NULL,
  expires_at text COLLATE "C" DEFAULT ''::text NOT NULL,
  CONSTRAINT resource_names_pkey PRIMARY KEY (kind, org, name)
);
CREATE INDEX idx_resource_names_id ON public.resource_names USING btree (kind, org, id);

CREATE TABLE public.resources (
  kind text NOT NULL,
  id text NOT NULL,
  data bytea NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  list_org text COLLATE "C",
  list_created_at text COLLATE "C",
  list_index_revision integer,
  list_indexed_at timestamp with time zone,
  CONSTRAINT resources_pkey PRIMARY KEY (kind, id)
);
CREATE INDEX idx_resources_list_created ON public.resources USING btree (kind, list_created_at, id COLLATE "C");
CREATE INDEX idx_resources_list_org ON public.resources USING btree (kind, list_org, list_created_at, id COLLATE "C");
CREATE INDEX idx_resources_list_revision ON public.resources USING btree (kind, list_index_revision);
CREATE INDEX idx_resources_list_unproven ON public.resources USING btree (kind, id) WHERE (list_indexed_at IS DISTINCT FROM updated_at);

CREATE TABLE public.routine_fires (
  routine_id text NOT NULL,
  fire_id text NOT NULL,
  org text DEFAULT ''::text NOT NULL,
  nominal_fire_time text NOT NULL,
  origin text NOT NULL,
  outcome text NOT NULL,
  reason text DEFAULT ''::text NOT NULL,
  run_id text DEFAULT ''::text NOT NULL,
  fired_by bytea,
  recorded_at text DEFAULT ''::text NOT NULL,
  completed_at text DEFAULT ''::text NOT NULL,
  CONSTRAINT routine_fires_pkey PRIMARY KEY (routine_id, fire_id)
);
CREATE INDEX idx_routine_fires_order ON public.routine_fires USING btree (routine_id, nominal_fire_time, fire_id);
CREATE INDEX idx_routine_fires_prune ON public.routine_fires USING btree (recorded_at);
CREATE INDEX idx_routine_fires_recency ON public.routine_fires USING btree (routine_id, recorded_at DESC);

CREATE TABLE public.search_index (
  kind text NOT NULL,
  resource_id text NOT NULL,
  name text DEFAULT ''::text NOT NULL,
  description text DEFAULT ''::text NOT NULL,
  tags text DEFAULT ''::text NOT NULL,
  org text DEFAULT ''::text NOT NULL,
  visibility text DEFAULT ''::text NOT NULL,
  created_at bigint DEFAULT 0 NOT NULL,
  seq bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  search tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('english'::regconfig, COALESCE(name, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(tags, ''::text)), 'B'::"char")) || setweight(to_tsvector('english'::regconfig, COALESCE(description, ''::text)), 'C'::"char"))) STORED,
  CONSTRAINT search_index_pkey PRIMARY KEY (kind, resource_id)
);
CREATE INDEX idx_search_index_list ON public.search_index USING btree (created_at DESC, seq DESC);
CREATE INDEX idx_search_index_tsv ON public.search_index USING gin (search);

CREATE TABLE public.session_event_heads (
  session_id text NOT NULL,
  org text DEFAULT ''::text NOT NULL,
  last_seq bigint NOT NULL,
  last_processed_at text NOT NULL,
  CONSTRAINT session_event_heads_pkey PRIMARY KEY (session_id)
);
CREATE INDEX idx_session_event_heads_org ON public.session_event_heads USING btree (org);

CREATE TABLE public.session_events (
  session_id text NOT NULL,
  seq bigint NOT NULL,
  event_id text NOT NULL,
  run_id text DEFAULT ''::text NOT NULL,
  thread_id text DEFAULT ''::text NOT NULL,
  type text NOT NULL,
  org text DEFAULT ''::text NOT NULL,
  processed_at text NOT NULL,
  data bytea NOT NULL,
  opens_gate text DEFAULT ''::text NOT NULL,
  closes_gate text DEFAULT ''::text NOT NULL,
  gate_revision integer DEFAULT 0 NOT NULL,
  CONSTRAINT session_events_pkey PRIMARY KEY (session_id, seq)
);
CREATE INDEX idx_session_events_closes_gate ON public.session_events USING btree (session_id, closes_gate) WHERE (closes_gate <> ''::text);
CREATE UNIQUE INDEX idx_session_events_event_id ON public.session_events USING btree (session_id, event_id);
CREATE INDEX idx_session_events_gate_revision ON public.session_events USING btree (gate_revision);
CREATE INDEX idx_session_events_opens_gate ON public.session_events USING btree (session_id, opens_gate) WHERE (opens_gate <> ''::text);
CREATE INDEX idx_session_events_org ON public.session_events USING btree (org);
CREATE INDEX idx_session_events_org_type ON public.session_events USING btree (org, type, processed_at, event_id);
CREATE INDEX idx_session_events_run ON public.session_events USING btree (session_id, run_id, seq);
CREATE INDEX idx_session_events_type ON public.session_events USING btree (session_id, type, seq);

CREATE TABLE public.session_queued_messages (
  session_id text NOT NULL,
  event_id text NOT NULL,
  org text DEFAULT ''::text NOT NULL,
  sender text DEFAULT ''::text NOT NULL,
  turn bytea NOT NULL,
  lane bytea DEFAULT '\x'::bytea NOT NULL,
  CONSTRAINT session_queued_messages_pkey PRIMARY KEY (session_id, event_id)
);
CREATE INDEX idx_session_queued_messages_org ON public.session_queued_messages USING btree (org);
